/* ==========================================================================
 *  AbcMall 阿帕茨商城 —— 商品数据补充脚本 (abcmall_补充.sql)
 *  适用前提 : 先执行 abcmall.sql 完成建库建表与种子数据
 *  补充内容 : product_brand / product / product_spec / product_sku / product_attr 五张表
 *  数据规模 : 新增品牌 38 个(id 11-48)，新增商品 236 个(id 21-256)
 *            以「数码电子-手机通讯(101)」「数码电子-电脑办公(102)」为主，
 *            另补平板电脑(103)、耳机音响(104)、智能穿戴(105)少量商品
 *  主键区间 : brand 11-48 / product 21-256 / spec 1001 起 / sku 10001 起 / attr 20001 起，与原有数据不冲突
 *  用法     : mysql -uroot -proot abcmall < abcmall_补充.sql
 * ========================================================================== */

USE `abcmall`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

/* ---------- 补充品牌 (id 11-48) ---------- */
;

/* ---------- 补充商品 SPU (id 21-256) ---------- */
;

/* ---------- 补充商品规格项 (id 1001 起) ---------- */
;

/* ---------- 补充商品规格值 product_spec_value (id 2001 起) ---------- */
/* 说明 : SKU 的 spec_json 已内嵌完整规格名/值，本段为可选补充，保持规格表数据完整 */
;

/* ---------- 补充商品 SKU (id 10001 起) ---------- */
;

/* ---------- 补充商品参数 (id 20001 起) ---------- */
;

SET FOREIGN_KEY_CHECKS = 1;

/* ==========================================================================
 *  数据校验
 * ========================================================================== */
SELECT '补充-品牌' AS 表, COUNT(*) AS 数量 FROM product_brand WHERE id BETWEEN 11 AND 48
UNION ALL SELECT '补充-商品SPU', COUNT(*) FROM product WHERE id BETWEEN 21 AND 256
UNION ALL SELECT '补充-规格项', COUNT(*) FROM product_spec WHERE id BETWEEN 1001 AND 9999
UNION ALL SELECT '补充-规格值', COUNT(*) FROM product_spec_value WHERE id BETWEEN 2001 AND 9999
UNION ALL SELECT '补充-商品SKU', COUNT(*) FROM product_sku WHERE id BETWEEN 10001 AND 19999
UNION ALL SELECT '补充-商品参数', COUNT(*) FROM product_attr WHERE id BETWEEN 20001 AND 29999;
